%[text] # SALSAT Data Visualisation
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## PSD Measurement Table
%[text] Importing the data retreived from SALSAT website.
function [table, psd, freqs] = read_salsat_tab(path)
    table = readtable(path);
    table = renamevars( ...
                    table, ...
                    table.Properties.VariableNames, ...
                    ["id",	"Date",	"Lat",	"Lon",	"Band",	"Center Freq [MHz]",	"Bandwidth [MHz]",	"Median",	"Integration Time",	"PSD"] ...
                    );
    psd = str2double(split(table(:,"PSD").Variables,","));

    freqs = linspace( ...
                table(1,:).("Center Freq [MHz]")-table(1,:).("Bandwidth [MHz]")/2, ...
                table(1,:).("Center Freq [MHz]")+table(1,:).("Bandwidth [MHz]")/2, ...
                width(psd) ...
                );

end
[salsat_tab,salsat_psd, salsat_freqs] = read_salsat_tab(fileparts(matlab.desktop.editor.getActiveFilename)+"/salsat_raw/fft_data_2023-04-19 12_29_29 - 2023-04-19 12_30_04.csv");




%%
date_choice = 5; %[control:slider:8429]{"position":[15,16]}
fig = figure();  %[output:7f09ffd2]
fig.Position(3:4) = [1000, 500]; %[output:7f09ffd2]
hold on %[output:7f09ffd2]
title("PSD at "+string(salsat_tab(date_choice,:).Date)) %[output:7f09ffd2]
plot(salsat_freqs,salsat_psd(date_choice,:)) %[output:7f09ffd2]
xlabel("Frequency (MHz)") %[output:7f09ffd2]
ylim([-100,0]) %[output:7f09ffd2]
ylabel("RSSI (dB)") %[output:7f09ffd2]
hold off %[output:7f09ffd2]
%%
%[text] Zooming on the area of major interference:
fig = figure();  %[output:6fae22ea]
fig.Position(3:4) = [1000, 1000]'; %[output:6fae22ea]
hold on %[output:6fae22ea]

subplot(2,1,1) %[output:6fae22ea]
plot(salsat_freqs,salsat_psd(4,:)) %[output:6fae22ea]
title("PSD at "+string(salsat_tab(4,:).Date)) %[output:6fae22ea]
xlabel("Frequency (MHz)") %[output:6fae22ea]
ylabel("RSSI (dB)") %[output:6fae22ea]
xlim([434,436.5]) %[output:6fae22ea]


subplot(2,1,2) %[output:6fae22ea]
plot(salsat_freqs,salsat_psd(2,:)) %[output:6fae22ea]
title("PSD at "+string(salsat_tab(2,:).Date)) %[output:6fae22ea]
xlabel("Frequency (MHz)") %[output:6fae22ea]
ylabel("RSSI (dB)") %[output:6fae22ea]
xlim([434,436.5]) %[output:6fae22ea]
xticks([434:0.1:436.5]) %[output:6fae22ea]
grid minor %[output:6fae22ea]
hold off %[output:6fae22ea]
%%
%[text] ## Looking at other SALSAT readings, and showing orbital position
Location = "over_uk"; %[control:dropdown:84a4]{"position":[12,21]}
path = fileparts(matlab.desktop.editor.getActiveFilename)+"/salsat_raw/"+Location+"/";
file_list = dir(path+"*.csv");
file_list = string({file_list.name});
file = file_list(5); % Sometimes throws error if index chosen higher than available in different location %[control:dropdown:7182]{"position":[8,20]}

[table, psd, freqs] = read_salsat_tab(path+file);
salsat_alt = 530e3; 

fig = figure();  %[output:488b303d]
fig.Position(3:4) = [500, 500]; %[output:488b303d]
hold on %[output:488b303d]
% Remove cart axes
set(gca,'XColor', 'none','YColor','none') %[output:488b303d]
set(gca, 'color', 'none'); %[output:488b303d]

gx1 = geoaxes; %[output:488b303d]
geoplot(table.Lat, table.Lon,"x-",table(1,:).Lat, table(1,:).Lon,"x-red",'LineWidth',2,"DisplayName","SALSAT Path") %[output:488b303d]

latlim = [20 65];
lonlim = [-25 15];
geolimits(gx1,latlim,lonlim) %[output:488b303d]


hold off %[output:488b303d]

fig = figure();  %[output:3d4320b3]
fig.Position(3:4) = [2000, 500]; %[output:3d4320b3]
hold on %[output:3d4320b3]

subplot(1,2,1) %[output:3d4320b3]
[X,Y] = meshgrid(freqs,datenum(table.Date));
C = gradient(psd);
waterfall(X,Y,psd,C) %[output:3d4320b3]
%yt=yticks; yticks(yt(1:2:end))  % not going to be room for very many tick labels so cut 'em down...
datetick('y','hh:mm:ss','keepticks','keeplimits') %[output:3d4320b3]
colorbar %[output:3d4320b3]
view([349 77]) %[output:3d4320b3]

subplot(1,2,2) %[output:3d4320b3]
imagesc(freqs,table.Date,psd) %[output:3d4320b3]
zlim([-inf +inf]) %[output:3d4320b3]
colorbar %[output:3d4320b3]

hold off %[output:3d4320b3]
freq_slice = [433 435]; %[control:rangeslider:5deb]{"position":[14,23]}

for i = 1:length(table.Date) %[output:group:3ef4e78e]
    fig = figure();  %[output:2015845b] %[output:59484d8e] %[output:26a07bbd] %[output:1dd6fda3] %[output:5b6c6d35] %[output:5584bb78] %[output:8791c481] %[output:6be37567] %[output:91ab60e9] %[output:8cea0d5e] %[output:18f73500] %[output:6c33a540]
    fig.Position(3:4) = [1000,250]; %[output:2015845b] %[output:59484d8e] %[output:26a07bbd] %[output:1dd6fda3] %[output:5b6c6d35] %[output:5584bb78] %[output:8791c481] %[output:6be37567] %[output:91ab60e9] %[output:8cea0d5e] %[output:18f73500] %[output:6c33a540]
    plot(freqs,psd(i,:))
    title(string(table(i,:).Date))
    xlim(freq_slice)
end %[output:group:3ef4e78e]

